    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "bad_deploy",
      "mechanism": "Worker v1.1 (deployed t=515) introduced a bug that causes the worker process to crash repeatedly (health-check restarts from t=550), preventing it from consuming the 676 pending messages and orphaning orders; the premature-ack theory is ruled out since no messages are in an acknowledged-but-unprocessed state.",
      "supporting": ["E1", "E4", "E5", "E6", "E7", "E16"],
      "refuting": ["E17"],
      "explains": ["I2_no_orphaned_orders"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "worker"}},
        {"action": "requeue_orphaned_orders", "params": {}}
      ]
    }
  ],
  "summary": "Worker v1.1 (t=515) introduced a crash bug causing continuous health-check restarts, leaving 676 messages pending and orphaning orders; premature acknowledgement is ruled out by the database evidence."
}
```
